import{_ as e,o as a,c as t,a4 as i}from"./chunks/framework.BMj-uaUw.js";const k=JSON.parse('{"title":"单元 4 · AI 协作：别让它把 Vue 2 的写法带进来","description":"","frontmatter":{},"headers":[{"level":2,"title":"这一章哪些活能交给 AI","slug":"这一章哪些活能交给-ai","link":"#这一章哪些活能交给-ai","children":[]},{"level":2,"title":"提示词怎么写","slug":"提示词怎么写","link":"#提示词怎么写","children":[{"level":3,"title":"1. 让它把选项式 API 改写成组合式 API","slug":"_1-让它把选项式-api-改写成组合式-api","link":"#_1-让它把选项式-api-改写成组合式-api","children":[]},{"level":3,"title":"2. 让它给你一份旧写法对照清单","slug":"_2-让它给你一份旧写法对照清单","link":"#_2-让它给你一份旧写法对照清单","children":[]},{"level":3,"title":"3. 让它帮你排查响应式失效","slug":"_3-让它帮你排查响应式失效","link":"#_3-让它帮你排查响应式失效","children":[]}]},{"level":2,"title":"AI 在这一章容易错什么","slug":"ai-在这一章容易错什么","link":"#ai-在这一章容易错什么","children":[{"level":3,"title":"混进 Vue 2 的写法","slug":"混进-vue-2-的写法","link":"#混进-vue-2-的写法","children":[]},{"level":3,"title":"解构之后失去响应性，它却说没问题","slug":"解构之后失去响应性-它却说没问题","link":"#解构之后失去响应性-它却说没问题","children":[]},{"level":3,"title":"把 .value 的规则说反","slug":"把-value-的规则说反","link":"#把-value-的规则说反","children":[]},{"level":3,"title":"用 reactive 装基本类型","slug":"用-reactive-装基本类型","link":"#用-reactive-装基本类型","children":[]}]},{"level":2,"title":"怎么验收 AI 的产出","slug":"怎么验收-ai-的产出","link":"#怎么验收-ai-的产出","children":[]},{"level":2,"title":"练习","slug":"练习","link":"#练习","children":[{"level":3,"title":"给 AI 一段 Vue 2 的代码，让它改写，然后逐行核对","slug":"给-ai-一段-vue-2-的代码-让它改写-然后逐行核对","link":"#给-ai-一段-vue-2-的代码-让它改写-然后逐行核对","children":[]}]}],"relativePath":"unit04/ai-collaboration.md","filePath":"unit04/ai-collaboration.md","lastUpdated":1789356894000}'),n={name:"unit04/ai-collaboration.md"};function l(o,s,p,d,r,c){return a(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="单元-4-·-ai-协作-别让它把-vue-2-的写法带进来" tabindex="-1">单元 4 · AI 协作：别让它把 Vue 2 的写法带进来 <a class="header-anchor" href="#单元-4-·-ai-协作-别让它把-vue-2-的写法带进来" aria-label="Permalink to &quot;单元 4 · AI 协作：别让它把 Vue 2 的写法带进来&quot;">​</a></h1><p>从这一章开始你写的是真正的 Vue 代码。AI 在这里能帮你很多 —— 它见过的 Vue 代码比你多几百倍，解释概念、改写写法、排查响应式失效，它都拿手。</p><p>但它也有一个很具体的短板：<strong>它见过的 Vue 2 代码同样比你多几百倍。</strong> Vue 2 存在了七年，Vue 3 的组合式写法是后来才普及的，训练数据里两者的比例并不偏向新的那一方。所以它给你的代码里，经常混着几处早就该淘汰的写法。</p><p>这一节的目标不是“怎么让它写 Vue 代码”，而是<strong>怎么一眼认出它写的是哪一版的 Vue</strong>。</p><h2 id="这一章哪些活能交给-ai" tabindex="-1">这一章哪些活能交给 AI <a class="header-anchor" href="#这一章哪些活能交给-ai" aria-label="Permalink to &quot;这一章哪些活能交给 AI&quot;">​</a></h2><p>判断标准：<strong>解释和改写可以交，判断“这算不算 Vue 3 写法”不能交 —— 因为这事它自己就常出错。</strong></p><table tabindex="0"><thead><tr><th>任务</th><th>能交给 AI 吗</th><th>为什么</th></tr></thead><tbody><tr><td>把选项式 API 改写成组合式 API</td><td>可以</td><td>改写本身是机械工作，但你要逐行核对</td></tr><tr><td>解释一个响应式为什么没生效</td><td>可以</td><td>它见过的失效场景比教程列的全</td></tr><tr><td>列出 Vue 3 里已经不再推荐的旧写法</td><td>可以</td><td>当检查清单用，比你自己回忆省事</td></tr><tr><td>讲清 <code>Proxy</code> 与 <code>Object.defineProperty</code> 的差别</td><td>可以</td><td>讲到能判断对错这一层就够</td></tr><tr><td>对比 <code>ref</code> 与 <code>reactive</code> 的取值场景</td><td>可以</td><td>但最终按项目的约定来</td></tr><tr><td>判断“你写的这段是不是 Vue 3 写法”</td><td><strong>不能直接信</strong></td><td>它常把自己混进去的 Vue 2 写法当成正确的</td></tr><tr><td>决定用不用某个新 API</td><td><strong>不行</strong></td><td>取决于项目的 Vue 版本下限，它不知道</td></tr><tr><td>让它直接改你 <code>src/</code> 下的文件</td><td><strong>不行</strong></td><td>改完你还是得逐行读，不如自己写一遍</td></tr></tbody></table><p>中间那行是这一章的核心矛盾：<strong>你请它帮你检查有没有 Vue 2 残留，而它自己就是残留的来源。</strong> 所以检查这件事必须你自己会做。</p><h2 id="提示词怎么写" tabindex="-1">提示词怎么写 <a class="header-anchor" href="#提示词怎么写" aria-label="Permalink to &quot;提示词怎么写&quot;">​</a></h2><h3 id="_1-让它把选项式-api-改写成组合式-api" tabindex="-1">1. 让它把选项式 API 改写成组合式 API <a class="header-anchor" href="#_1-让它把选项式-api-改写成组合式-api" aria-label="Permalink to &quot;1. 让它把选项式 API 改写成组合式 API&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把下面这段选项式 API 的组件改写成 &lt;script setup&gt; 的组合式写法：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴完整组件]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 改完把“改了哪些地方”列成一个对照表，左列原写法，右列新写法</span></span>
<span class="line"><span>2. 特别注意这几处：data、computed、methods、watch、</span></span>
<span class="line"><span>   生命周期钩子、this 的引用方式</span></span>
<span class="line"><span>3. 如果某处你没有把握，单独列出来，不要改</span></span></code></pre></div><p><strong>为什么这么写</strong>：第 1 点的对照表是关键 —— 改写本身它做得不错，但改写理由它通常不写。有了对照表，你就能逐行核对“它为什么这么改”，而不是看一遍“像那么回事”就收下。第 3 点给它留了退路，宁可它标一个“没把握”，也好过它猜一个看起来合理的写法。</p><h3 id="_2-让它给你一份旧写法对照清单" tabindex="-1">2. 让它给你一份旧写法对照清单 <a class="header-anchor" href="#_2-让它给你一份旧写法对照清单" aria-label="Permalink to &quot;2. 让它给你一份旧写法对照清单&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请列一份对照表：Vue 2 里的写法 / Vue 3 里对应的写法 / 为什么改。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>覆盖这些方面：创建应用、注册插件、数据声明、定义方法、注册全局组件、</span></span>
<span class="line"><span>生命周期钩子的名字、数组和对象的更新方式、模板里的过滤器、事件修饰符。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 只列确实变了的部分，不要凑数</span></span>
<span class="line"><span>2. 每一项给一小段代码，能直接看出新旧差别</span></span>
<span class="line"><span>3. “为什么改”用一句话说清，我要的是判断依据，不是原理</span></span></code></pre></div><p><strong>为什么这么写</strong>：这份对照表是一次性投入、长期用的东西 —— 把它存进自己的笔记，以后审 AI 产出的代码时对着扫一遍就行。要求“只列确实变了的部分”是因为它很容易把没变的也列进来凑数，那样清单就没用了。要求“一句话说清为什么改”，是为了让你能判断出它有没有把某两件事的因果关系说反。</p><h3 id="_3-让它帮你排查响应式失效" tabindex="-1">3. 让它帮你排查响应式失效 <a class="header-anchor" href="#_3-让它帮你排查响应式失效" aria-label="Permalink to &quot;3. 让它帮你排查响应式失效&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我改了数据，界面不更新。这是相关代码：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴 script setup 部分和模板部分]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>我期望的行为是：[说清什么操作之后界面应该变成什么样]</span></span>
<span class="line"><span>我实际看到的是：[说清实际是什么样]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请回答：</span></span>
<span class="line"><span>1. 按可能性排序，列出可能导致不更新的原因</span></span>
<span class="line"><span>2. 每个原因对应的验证办法，要具体到“看哪一行 / 加什么输出”</span></span>
<span class="line"><span>3. 你从这个片段里能直接确认的原因是什么，直接说结论</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要建议我换一种写法重写，我要先知道现在为什么不行。</span></span></code></pre></div><p><strong>为什么这么写</strong>：响应式失效是一类“现象相同、原因各不同”的问题 —— 可能是解构丢了响应性，可能是改了对象里新增的属性，可能是模板里用了没在 <code>setup</code> 里暴露的变量。让它排序给原因，比让它直接给一段新代码有用得多。最后一句是在拦它“别管为什么了，我给你重写一版” —— 那样你学到了零。</p><h2 id="ai-在这一章容易错什么" tabindex="-1">AI 在这一章容易错什么 <a class="header-anchor" href="#ai-在这一章容易错什么" aria-label="Permalink to &quot;AI 在这一章容易错什么&quot;">​</a></h2><h3 id="混进-vue-2-的写法" tabindex="-1">混进 Vue 2 的写法 <a class="header-anchor" href="#混进-vue-2-的写法" aria-label="Permalink to &quot;混进 Vue 2 的写法&quot;">​</a></h3><p><strong>现象</strong>：它给的代码里出现这些东西：</p><table tabindex="0"><thead><tr><th>你看到的</th><th>问题在哪</th></tr></thead><tbody><tr><td><code>new Vue({ ... })</code></td><td>创建应用现在用 <code>createApp()</code></td></tr><tr><td><code>Vue.use(SomePlugin)</code></td><td>现在写成 <code>app.use(SomePlugin)</code></td></tr><tr><td><code>filters: { ... }</code> 和模板里的 <code>{{ x | fmt }}</code></td><td>过滤器已经被移除，改用计算属性或函数</td></tr><tr><td><code>this.$set(obj, &#39;key&#39;, value)</code></td><td>响应式换成 <code>Proxy</code> 之后不再需要它</td></tr><tr><td><code>beforeDestroy</code> / <code>destroyed</code></td><td>钩子改名为 <code>onBeforeUnmount</code> / <code>onUnmounted</code></td></tr><tr><td>在 <code>setup</code> 里写 <code>this.xxx</code></td><td>组合式 API 里没有 <code>this</code></td></tr></tbody></table><p><strong>原因</strong>：Vue 2 存在的时间长，代码总量比 Vue 3 多。它在生成代码时，按“见过的频率”加权，而不是按“哪一版更新”。</p><p><strong>怎么处理</strong>：<strong>记住上面这张表，扫一遍它给的代码。</strong> 出现任何一个，就说明它这次是按 Vue 2 的记忆生成的，整段代码都要重新审 —— 不是只改这一处，而是它这一版的其他地方也可能有同类问题。</p><h3 id="解构之后失去响应性-它却说没问题" tabindex="-1">解构之后失去响应性，它却说没问题 <a class="header-anchor" href="#解构之后失去响应性-它却说没问题" aria-label="Permalink to &quot;解构之后失去响应性，它却说没问题&quot;">​</a></h3><p><strong>现象</strong>：你写了 <code>const { count } = state</code> 或 <code>const { title } = props</code>，然后发现改了 <code>state.count</code> 界面不动。你问它，它说“写法正确”。</p><p><strong>原因</strong>：解构拿到的是当时那一刻的<strong>值</strong>，不是那个响应式引用本身。它判断“对不对”的依据是语法有没有错，而这里的语法完全没问题 —— 这是运行时行为的问题，它看不出来。</p><p><strong>怎么处理</strong>：记住这条规则 —— <strong>从 <code>props</code> 或 <code>reactive</code> 对象里取值时，不要解构基本类型。</strong> 需要解构时用 <code>toRefs</code> 或 <code>toRef</code>：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { toRefs, toRef } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vue&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// props 解构：用 toRef 保住那一项的响应性</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> toRefs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(props)          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 全部解构</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> title</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> toRef</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(props, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;title&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 只取一项</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// reactive 对象解构同理</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> toRefs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(state)</span></span></code></pre></div><p>注意 <code>toRefs</code> 之后拿到的是 <code>ref</code>，脚本里读写要带 <code>.value</code>，模板里不带。这正好是下面那条。</p><h3 id="把-value-的规则说反" tabindex="-1">把 <code>.value</code> 的规则说反 <a class="header-anchor" href="#把-value-的规则说反" aria-label="Permalink to &quot;把 \`.value\` 的规则说反&quot;">​</a></h3><p><strong>现象</strong>：它说“<code>ref</code> 在模板里要写 <code>.value</code>，在脚本里不用写”，或者反过来。</p><p><strong>原因</strong>：这两条规则方向相反，很容易说串。而且它给的代码有时自己也不一致。</p><p><strong>怎么处理</strong>：记死一句话 —— <strong>脚本里要 <code>.value</code>，模板里不要。</strong></p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> count</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">count.value</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                              // 脚本里：要 .value</span></span></code></pre></div><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 模板里：不要 .value --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;{{ count }}&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>为什么会这样：模板里的顶层 <code>ref</code> 会被自动解包。<strong>但自动解包只对顶层生效</strong> —— 如果 <code>ref</code> 是某个对象的一个属性，模板里照样要 <code>.value</code>。这一条边界它常讲错，也是<a href="/frontend-engineering-course/unit04/04-reactivity.html">4.4</a>里那个“自动解包的规则与边界”专门讲的。</p><h3 id="用-reactive-装基本类型" tabindex="-1">用 <code>reactive</code> 装基本类型 <a class="header-anchor" href="#用-reactive-装基本类型" aria-label="Permalink to &quot;用 \`reactive\` 装基本类型&quot;">​</a></h3><p><strong>现象</strong>：它写 <code>const count = reactive(0)</code>，或者 <code>const name = reactive(&#39;&#39;)</code>。</p><p><strong>原因</strong>：<code>reactive</code> 和 <code>ref</code> 的功能有重叠，它有时不分场景地混用。</p><p><strong>怎么处理</strong>：一句话判断 —— <strong><code>reactive</code> 只接受对象和数组，基本类型一律用 <code>ref</code>。</strong> 写 <code>reactive(0)</code> 不会报错，但返回的东西不是你要的，改它界面也不会动。这个错比语法错更难查，因为控制台是干净的。</p><details class="details custom-block"><summary>还有一类错误：在插值表达式里写语句或复杂运算</summary><p><strong>现象</strong>：它给你写 <code>{{ list.filter(i =&gt; i.status === &#39;SIGNING&#39;).length }}</code>、<code>{{ price.toFixed(2) * count }}</code>，甚至 <code>{{ count = 10 }}</code>。</p><p><strong>原因</strong>：模板里能写表达式，但只能写<strong>表达式</strong>，不能写语句，也不适合做复杂运算。它对这条边界通常不敏感，因为语法上大多数情况确实能跑。</p><p><strong>怎么处理</strong>：三条判断标准，扫一眼它的模板就能用：</p><ol><li><strong>里面有没有赋值</strong>（<code>=</code>）？有就是语句，模板里不合法。</li><li><strong>里面有没有循环或条件分支的完整逻辑</strong>？有就该抽成计算属性。</li><li><strong>同一段运算在模板里出现两次以上</strong>？抽成计算属性，顺便拿到缓存。</li></ol><p>按<a href="/frontend-engineering-course/unit04/02-template-syntax.html">4.2</a>里的说法，插值表达式只该放“一眼能看出结果”的东西。改法就是抽出来：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 模板里改成 {{ signingCount }}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> signingCount</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> computed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> list.value.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">filter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">i</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i.status </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;SIGNING&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">length</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>多写一行，换来的是模板还能读懂，以及这段运算不会每次渲染都重算一遍。</p></details><h2 id="怎么验收-ai-的产出" tabindex="-1">怎么验收 AI 的产出 <a class="header-anchor" href="#怎么验收-ai-的产出" aria-label="Permalink to &quot;怎么验收 AI 的产出&quot;">​</a></h2><p>这一章的产出是 Vue 组件代码。验收动作分两层：先扫旧写法，再验运行时行为。</p><ul><li>[ ] 代码里没有 <code>new Vue</code>、<code>Vue.use</code>、<code>filters</code>、<code>this.$set</code>、<code>beforeDestroy</code>、<code>this.xxx</code></li><li>[ ] 没有从 <code>props</code> 或 <code>reactive</code> 对象里直接解构基本类型；需要解构时用了 <code>toRefs</code> 或 <code>toRef</code></li><li>[ ] <code>ref</code> 的取值写对了：脚本里带 <code>.value</code>，模板里不带</li><li>[ ] 没有用 <code>reactive</code> 装基本类型</li><li>[ ] 插值表达式里没有赋值，没有复杂运算，重复的运算已经抽成计算属性</li><li>[ ] 三句话检查能过：说得出它做了什么、为什么这么写、出错会怎么表现</li><li>[ ] 你自己在浏览器里点一遍，界面按预期更新了</li><li>[ ] 控制台没有报错和警告</li></ul><p>前五条对应“先是 Vue 3 的写法”，第六、七条对应“真的能跑”，最后一条对应“别把问题留给下周”。<strong>Vue 的很多错误只在控制台提示，界面上看不出来 —— 一定要开着控制台看一遍。</strong></p><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h2><h3 id="给-ai-一段-vue-2-的代码-让它改写-然后逐行核对" tabindex="-1">给 AI 一段 Vue 2 的代码，让它改写，然后逐行核对 <a class="header-anchor" href="#给-ai-一段-vue-2-的代码-让它改写-然后逐行核对" aria-label="Permalink to &quot;给 AI 一段 Vue 2 的代码，让它改写，然后逐行核对&quot;">​</a></h3><p><strong>任务</strong>：自己找一段 Vue 2 的选项式 API 代码（可以从旧教程、旧项目里找，也可以按<a href="/frontend-engineering-course/unit04/01-declarative.html">4.1</a>的字段自己写一段），让 AI 改写成组合式 API，然后<strong>逐行核对，记录它改对了哪几处、漏了哪几处</strong>。</p><p><strong>要求</strong>：记录里必须包含这四项：</p><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>原始代码</td><td>完整保留，注明它用了哪几处 Vue 2 的写法</td></tr><tr><td>AI 的改写结果</td><td>完整保留，不要只留你改完的版本</td></tr><tr><td>逐行核对表</td><td>三列：原写法 / 它改成了什么 / 对不对</td></tr><tr><td>漏改与错改清单</td><td>每一条写清你是怎么发现的、正确写法是什么</td></tr></tbody></table><details class="details custom-block"><summary>验收标准与参考思路</summary><p><strong>为什么要“逐行核对”而不是“跑一下看看”</strong>：因为改写错误的代码经常能跑起来。<code>beforeDestroy</code> 改成 <code>onBeforeUnmount</code> 漏了，表现只是卸载时的清理没执行 —— 页面上看不出异常，直到某天定时器越来越多。<strong>这类问题只能靠读代码发现。</strong></p><p><strong>思路提示</strong>：</p><ul><li>原始代码里至少要故意放 4 处 Vue 2 写法：<code>new Vue</code>、<code>filters</code>、<code>this.$set</code>、<code>beforeDestroy</code>。这样才有足够的机会看出它漏没漏。</li><li>核对时对着上面那张旧写法表逐个搜关键词，比从头读到尾可靠。</li><li>如果它顺手把 <code>filters</code> 改成了 <code>computed</code>，检查一下改完的行为一样不一样 —— 过滤器可以接收参数、可以用在多个地方，改成计算属性时这些地方容易走样。</li><li><strong>如果它改对了，也把“改对”记下来。</strong> 知道自己哪类问题不需要盯，同样是收获。</li></ul><p><strong>不合格的写法</strong>：</p><blockquote><p>让 AI 把 Vue 2 的代码改成 Vue 3 了，跑起来没问题。</p></blockquote><p>“跑起来没问题”这句话里没有任何可验证的信息。它漏掉了哪几处？漏掉的那几处会不会在特定操作下才暴露？</p><p><strong>合格的写法</strong>：</p><blockquote><p>原始代码里有 4 处 Vue 2 写法。AI 改对了 <code>new Vue</code> → <code>createApp</code>、 <code>this.$set</code> → 直接赋值，两处漏改：<code>filters</code> 保留了原样、 <code>beforeDestroy</code> 没改成 <code>onBeforeUnmount</code>。 漏掉 <code>filters</code> 是我搜 <code>filters</code> 关键词发现的； 漏掉 <code>beforeDestroy</code> 是我对着钩子对照表逐一比出来的 —— 页面上看不出问题，因为它只在卸载时执行。 我改成 <code>onBeforeUnmount</code> 之后，在钩子里加了一句输出， 切换路由时能看到它被执行了，才算确认。</p></blockquote><p>差别在于：后者把“怎么发现的”和“怎么确认改对了”都写清楚了。<strong>这份记录里最值钱的是那两条漏改 —— 它告诉你该盯哪几类地方。</strong></p></details><hr><p>上一节：<a href="/frontend-engineering-course/unit04/05-reactivity-principle.html">4.5 响应式原理初探</a> · 课后练习：<a href="/frontend-engineering-course/unit04/practice.html">单元 4 课后练习</a></p>`,54)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
